import Foundation
private let offset: UInt64 = 1_469_598_103_934_665_603
private let prime: UInt64 = 1_099_511_628_211
private func hash(_ seed: UInt64, _ value: UInt64) -> UInt64 { var result = seed; for index in 0..<8 { result ^= (value >> UInt64(index * 8)) & 255; result &*= prime }; return result }
private func row(_ output: SM64SnowmanWindOutput) -> [UInt64] { [UInt64(bitPattern: Int64(output.subAction)), UInt64(bitPattern: Int64(output.timer)), UInt64(bitPattern: Int64(output.moveYaw)), UInt64(bitPattern: Int64(output.dialogID)), UInt64(bitPattern: Int64(output.particleCount)), output.playWindSound ? 1 : 0] }
@main struct SM64SnowmanWindSmoke { static func main() { let idle = SM64SnowmanWindBehavior.update(.init(subAction: 0, timer: 0, originalYaw: 100, moveYaw: 100, angleToMario: 100, distanceToMario: 10_000, marioY: 0, homeY: 0, canActivateText: true, dialogComplete: false)); let talk = SM64SnowmanWindBehavior.update(.init(subAction: 1, timer: 1, originalYaw: 100, moveYaw: 100, angleToMario: 100, distanceToMario: 10_000, marioY: 0, homeY: 0, canActivateText: false, dialogComplete: true)); let blow = SM64SnowmanWindBehavior.update(.init(subAction: 2, timer: 2, originalYaw: 100, moveYaw: 100, angleToMario: 0x3000, distanceToMario: 100, marioY: 0, homeY: 0, canActivateText: false, dialogComplete: false)); precondition(idle.subAction == 1 && talk.subAction == 2); precondition(blow.moveYaw == 5476 && blow.particleCount == 12 && blow.playWindSound); var fingerprint = offset; for output in [idle, talk, blow] { for value in row(output) { fingerprint = hash(fingerprint, value) } }; print(String(format: "snowmanWindFingerprint=0x%016llx", fingerprint)); print("SM64 Modern Snowman wind smoke passed") } }
